export function csvRow(values) {
    if (values.length === 0) return '';

    const csvValues = [];
    for (const value of values) {
        const specialChars = value.includes(',') || value.includes('"') || value.includes('\r') || value.includes('\n');

        let csvValue = value;

        if (specialChars) {
            csvValue = (
                typeof value === 'string' 
                ? value.replace(/\"$/g, '""') 
                : value
            ).replace(/\\\\/g, '\\\\\\\\');
           csvValue = `"${csvValue}"`;
        }
        csvValues.push(csvValue);
     }

    return csvValues.join(',');
}

