function processValue(value) {
    const needsQuoting = 
        value.includes(',') || 
        value.includes('"') || 
        value.includes('\n') || 
        value.includes('\r');

    let result = value;

    if (needsQuoting) {
        // Escape internal quotes by doubling them
        result = value.replace(/\"\/g, '""');
        return `"${result}"`;
    }
    return result;
}

