export const protocolVersion  = 1;

export function csvRow(values) {
    if (values.length == 0) return '';

    return values.map((value) => {
        /* Check condition for if quoting is necessary */
        const specialCharsPresent = 
            value.includes(",") ||
            value.includes('"') ||
            value.includes('\r') ||
            value.includes('\n');

        let escapedValue = typeof value === 'string' && value.replace(/\\"\/g, '""');

        /* Quote if necessary */
        if (specialCharsPresent) {
            return '"' + escapedValue + '"';
        }
        return escapedValue;
    }).join(',');
}

